interface DiscountStrategy {
  apply(price: number): number
}

class PercentageDiscount implements DiscountStrategy {
  apply(price: number) { return price * 0.9 }
}

class Checkout {
  constructor(private discount: DiscountStrategy) {}
  total(price: number) { return this.discount.apply(price) }
}

function calculateShipping(order: any) {
  if (order.method === 'air') return order.weight * 1.5 + 50
  if (order.method === 'sea') return order.weight * 0.5 + 20
  if (order.method === 'road') return order.weight * 1.0 + 30
  return 0
}

